CREATE TABLE t(a INTEGER, b TEXT, c REAL, d NUMERIC, e BLOB, f);
INSERT INTO t VALUES (1, '1', 1.0, 1, x'31', 1), (2, '10', 2.5, '2', '2', '2'), (3, 'abc', 3.0, 3.5, 3, 'x');
SELECT a FROM t WHERE a < '2';
SELECT a FROM t WHERE a = '1';
SELECT a FROM t WHERE '2' > a;
SELECT a FROM t WHERE a < CAST(3 AS TEXT);
SELECT a FROM t WHERE b = 1;
SELECT a FROM t WHERE b < 2;
SELECT a FROM t WHERE c = '1';
SELECT a FROM t WHERE d = '2';
SELECT a FROM t WHERE e = 3;
SELECT a FROM t WHERE e = '2';
SELECT a FROM t WHERE f = 1;
SELECT a FROM t WHERE f = '1';
SELECT a FROM t WHERE a IN ('1', '2');
SELECT a FROM t WHERE b IN (1, 10);
SELECT a FROM t WHERE a BETWEEN '1' AND '2';
SELECT a, a = b, b = a, a < b, c = b, d = b FROM t;
SELECT a FROM t WHERE (a + 0) = '1';
SELECT a FROM t WHERE a = (SELECT '1');
SELECT a FROM t WHERE a IN (SELECT '1' UNION SELECT '3');
SELECT 1 = '1', '1' = 1, CAST(1 AS TEXT) = 1;
SELECT a FROM t WHERE a COLLATE NOCASE = '1';
SELECT CASE a WHEN '1' THEN 'one' ELSE 'other' END FROM t;
SELECT a FROM t WHERE b > 5;
SELECT a FROM t WHERE a > ?;
SELECT max(a) FROM t WHERE a < '3';
UPDATE t SET f = 9 WHERE a < '2';
SELECT * FROM t;
DELETE FROM t WHERE a > '2';
SELECT * FROM t;
